parameters.inputSchema:
={
  "type": "object",
  "properties": {
    "matched_requirements": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Requirements from the job description that the candidate meets based on their CV."
    },
    "missing_requirements": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Job requirements that are not demonstrated in the candidate's CV."
    },
    "strengths": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Candidate's strongest qualifications, achievements, and relevant experience."
    },
    "concerns": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Potential weaknesses, gaps, or concerns relevant to the job."
    },
    "yearsExperience": {
      "type": "number",
      "description": "Estimated total years of relevant professional experience. Return 0 if no relevant experience is demonstrated."
    },
    "topSkills": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Most relevant technical and professional skills of the candidate."
    },
    "error": {
      "type": "string",
      "description": "Error message if the CV text is unreadable, empty, or extraction fails. Leave empty if successful."
    }
  },
  "required": [
    "matched_requirements",
    "missing_requirements",
    "strengths",
    "concerns",
    "yearsExperience",
    "topSkills"
  ]
}

parameters.jsCode:
const items = $input.all();

return items.map(item => {
  const output = item.json.output || {};
  const score = output.score;
  const aiError = output.error;

  const valid = !aiError && typeof score === 'number' && score >= 50;

  let problem = null;

  if (aiError) {
    problem = aiError;
  } else if (typeof score !== 'number') {
    problem = 'Score is missing or is not a valid number';
  } else if (score < 50) {
    problem = `Candidate score is ${score}, which is below the minimum required score of 50`;
  }

  return {
    json: {
      ...item.json,
      valid,
      problem
    }
  };
});

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "score": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100,
      "description": "Candidate evaluation score from 0 to 100."
    },
    "recommendation": {
      "type": "string",
      "enum": ["interview", "maybe", "reject"],
      "description": "Final hiring recommendation based strictly on the score."
    },
    "interview_questions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "minItems": 5,
      "maxItems": 5,
      "description": "Five personalized interview questions."
    },
    "error": {
      "type": "string",
      "description": "Error message if the candidate data or job requirements are missing, corrupted, or cannot be evaluated. Leave empty if successful."
    }
  },
  "required": [
    "score",
    "recommendation",
    "interview_questions"
  ],
  "additionalProperties": false
}
